// InjectInfrastructure back-fills the call's global trace identifier (trace_id)
// when the request body's TraceId is empty. If the caller provided TraceId
// explicitly, its business value is respected and never overwritten.
// Billing point of sale, target branch and similar fields are NOT injected
// here; callers must provide them explicitly in the request.
func (b *BaseCoreReq) InjectInfrastructure(traceID string) {
	if traceID != "" && b.TraceId == nil {
		b.TraceId = &traceID
	}
}

